package com.eventhub.dto; import com.eventhub.entity.*; import java.time.Instant;
public record TicketResponse(String ticketId,String registrationNumber,String studentName,String eventTitle,Long eventId,java.time.LocalDate eventDate,String venue,RegistrationStatus status,Instant issuedAt,String qrCodeDataUrl){public static TicketResponse of(Ticket t,String qr){Registration r=t.getRegistration();return new TicketResponse(t.getTicketId(),r.getRegistrationNumber(),r.getUser().getFirstName()+" "+r.getUser().getLastName(),r.getEvent().getTitle(),r.getEvent().getId(),r.getEvent().getEventDate(),r.getEvent().getVenue().getName(),r.getStatus(),t.getIssuedAt(),qr);}}
